(function(){const c=window.APP_CONFIG,k='diag_teacher_session';const h=t=>({'apikey':c.supabaseKey,'Authorization':`Bearer ${t||c.supabaseKey}`,'Content-Type':'application/json'});async function r(p,o={}){const x=await fetch(c.supabaseUrl+p,{...o,headers:{...h(o.token),...(o.headers||{})}}),s=await x.text();let d;try{d=s?JSON.parse(s):null}catch{d=s}if(!x.ok)throw new Error(d?.msg||d?.message||d?.error_description||`Erreur ${x.status}`);return d}const g=()=>{try{return JSON.parse(localStorage.getItem(k)||'null')}catch{return null}},set=s=>localStorage.setItem(k,JSON.stringify(s));async function session(){let s=g();if(!s)return null;if(Date.now()/1000<(s.expires_at||0)-60)return s;try{s=await r('/auth/v1/token?grant_type=refresh_token',{method:'POST',body:JSON.stringify({refresh_token:s.refresh_token})});set(s);return s}catch{localStorage.removeItem(k);return null}}window.DiagnosticAPI={submit:d=>r('/rest/v1/diagnostic_submissions',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify(d)}),signIn:async(e,p)=>{const s=await r('/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email:e,password:p})});set(s);return s},signUp:(e,p)=>r('/auth/v1/signup',{method:'POST',body:JSON.stringify({email:e,password:p})}),session,signOut:()=>localStorage.removeItem(k),list:async()=>{const s=await session();if(!s)throw new Error('Session expirée');return r('/rest/v1/diagnostic_submissions?select=*&order=created_at.desc',{token:s.access_token})},updateObservation:async(id,v)=>{const s=await session();return r(`/rest/v1/diagnostic_submissions?id=eq.${encodeURIComponent(id)}`,{method:'PATCH',token:s.access_token,headers:{Prefer:'return=minimal'},body:JSON.stringify({teacher_observation:v})})}}})();
